def _set_span_attributes(span, kind, template_string, prompt_variables, version, attributes):
    """Helper to set span attributes."""

    span.set_attribute("neatlogs.internal", True)
    span_kind = kind if kind else "CHAIN"
    span.set_attribute("openinference.span.kind", span_kind)

    for key, value in attributes.items():
        span.set_attribute(key, value)


def _finalize_prompt_capture(span, is_prompt_template_obj, is_user_prompt_template_obj, logger):
    """Helper to finalize prompt variable capture after yield."""
    import json

    from ..prompt.template import PromptContext, UserPromptContext

    if is_prompt_template_obj:
        captured_vars = PromptContext.get_variables()
        if captured_vars:
            span.set_attribute(
                "llm.prompt_template_variables", json.dumps(captured_vars, default=str)
            )
            logger.debug(
                f"[trace] Auto-captured variables from PromptContext: {list(captured_vars.keys())}"
            )

    if is_user_prompt_template_obj:
        captured_user_vars = UserPromptContext.get_variables()
        if captured_user_vars:
            span.set_attribute(
                "llm.user_prompt_template_variables", json.dumps(captured_user_vars, default=str)
            )
            logger.debug(
                f"[trace] Auto-captured variables from UserPromptContext: {list(captured_user_vars.keys())}"
            )

        # Also stamps metadata from neatlogs.wrap(..., **workflow_attrs)
        # while a metadata-bound wrapped client call is active. Both helpers
        # no-op when their context is inactive; child spans are skipped.
        if span.parent is None:
            from .._wrap_utils import apply_wrap_context_attributes
            from .end_user import apply_end_user_attributes
            from .session import apply_session_attributes

            apply_wrap_context_attributes(span, is_root=True)
            apply_session_attributes(span, None, is_root=True)
            apply_end_user_attributes(span, None, None, is_root=True)

        span_kind = span.attributes.get("openinference.span.kind") if span.attributes else None

        is_llm_span = (
            span_kind == "LLM"
            or "chat" in span.name.lower()
            or "completion" in span.name.lower()
            or "generate" in span.name.lower()
            or "embedding" in span.name.lower()
        )
        if not is_llm_span:
            return

        from opentelemetry.context import get_current, get_value

        from ..prompt.template import PromptContext, UserPromptContext

        ctx = get_current()
        variables_json = get_value("neatlogs.system_prompt_variables", context=ctx)
        template = get_value("neatlogs.system_prompt_template", context=ctx)
        prompt_key = get_value("neatlogs.system_prompt_key", context=ctx)
        version_val = get_value("neatlogs.prompt_version", context=ctx)

        if not variables_json:
            captured_vars = PromptContext.get_variables()
            if captured_vars:
                variables_json = json.dumps(captured_vars, default=str)

        if not template:
            captured_template = PromptContext.get_template()
            if captured_template:
                template = captured_template

        user_template = get_value("neatlogs.user_prompt_template", context=ctx)
        user_variables_json = get_value("neatlogs.user_prompt_variables", context=ctx)

        if not user_template:
            captured_user_template = UserPromptContext.get_template()
            if captured_user_template:
                user_template = captured_user_template

        if not user_variables_json:
            captured_user_vars = UserPromptContext.get_variables()
            if captured_user_vars:
                user_variables_json = json.dumps(captured_user_vars, default=str)

        if self.debug:
            logger.debug(f"[SpanProcessor.on_start] LLM span '{span.name}' starting")
            logger.debug(f"  variables_json from context: {variables_json}")
            logger.debug(f"  template from context: {template}")
            logger.debug(f"  version from context: {version_val}")
            logger.debug(f"  user_template from context: {user_template}")
            logger.debug(f"  user_variables_json from context: {user_variables_json}")

        if variables_json:
            span.set_attribute("llm.prompt_template_variables", variables_json)
        if template:
            span.set_attribute("llm.prompt_template", template)
            existing_prompt_key = (span.attributes or {}).get("neatlogs.llm.prompt_key") or (
                span.attributes or {}
            ).get("traceloop.prompt.key")
            if prompt_key and not existing_prompt_key:
                span.set_attribute("neatlogs.llm.prompt_key", prompt_key)
        if version_val:
            span.set_attribute("llm.prompt_template.version", version_val)
        if user_template:
            span.set_attribute("llm.user_prompt_template", user_template)
        if user_variables_json:
            span.set_attribute("llm.user_prompt_template_variables", user_variables_json)
    finally:
        self.perf_stats["on_start_time"] += time.perf_counter() - start_time

