// Fake Supabase REST endpoint for UI tests. Usage: node fake-postgrest.mjs <port> <screenshot.png>
import { createServer } from "node:http";
import { readFileSync } from "node:fs";

const [port, shot] = [Number(process.argv[2]), process.argv[3]];
const base = `http://127.0.0.1:${port}`;
const ids = {
  done: "00000000-0000-4000-8000-000000000001",
  running: "00000000-0000-4000-8000-000000000002",
  failed: "00000000-0000-4000-8000-000000000003",
  queued: "00000000-0000-4000-8000-000000000004",
};
const now = Date.now();
const iso = (s) => new Date(now - s * 1000).toISOString();
const run = (id, status, extra = {}) => ({
  id, url: "https://www.saucedemo.com/", goal: "Log in with the demo account, add a product to the cart and reach checkout.",
