});
const runs = {
  [ids.done]: run(ids.done, "done", { outcome: "achieved", reason: "I reached the checkout information page after adding the backpack to my cart.", cost_usd: "0.02428", finished_at: iso(60) }),
  [ids.running]: run(ids.running, "running"),
  [ids.failed]: run(ids.failed, "failed", { reason: "Anthropic API error: secret internal detail", finished_at: iso(100) }),
  [ids.queued]: run(ids.queued, "queued", { started_at: null }),
};
const steps = [
  { idx: 1, tool: "look", thought: "I want to see what this site is before doing anything.", input: {}, result: { url: "https://www.saucedemo.com/", title: "Swag Labs", summary: "On A login page for Swag Labs with a username field, a password field and a green Login button. Below the form a grey panel lists the accepted usernames and the shared password for all users. A login page for Swag Labs with a username field, a password field and a green Login button. Below the form a grey panel lists the accepted usernames and the shared password for all users. A login page for Sw", interactive: [] }, url: "https://www.saucedemo.com/", screenshot_path: null, created_at: iso(190) },
  { idx: 2, tool: "do", thought: "The page lists standard_user, so I'll type that into the username field.", input: { instruction: "type 'standard_user' into the username field" }, result: { success: true, changed: true, rung: "b", url: "https://www.saucedemo.com/" }, url: "https://www.saucedemo.com/", screenshot_path: `${base}/shot.png`, created_at: iso(180) },
  { idx: 3, tool: "note_friction", thought: "The password is hidden at the bottom of the page, which confused me.", input: { severity: "medium", expected: "The demo password next to the login form.", happened: "It was in a grey box below the fold." }, result: { recorded: true }, url: "https://www.saucedemo.com/", screenshot_path: null, created_at: iso(170) },
  { idx: 4, tool: "do", thought: "Now I'll add the backpack to my cart.", input: { instruction: "click the 'Add to cart' button for the backpack" }, result: { success: false, changed: false, reason: "no_effect", rung: null, url: "https://www.saucedemo.com/inventory.html" }, url: "https://www.saucedemo.com/inventory.html", screenshot_path: `${base}/shot.png`, created_at: iso(160) },
  { idx: 6, tool: "do", thought: "Open the cart.", input: { instruction: "click the cart icon" }, result: { success: true, changed: true, rung: "c", via: "locator.send_click_event" }, url: "https://www.saucedemo.com/cart.html", screenshot_path: null, created_at: iso(140) },
  { idx: 5, tool: "finish", thought: "I made it to checkout.", input: { outcome: "achieved", reason: "I reached the checkout information page." }, result: { finished: true }, url: "https://www.saucedemo.com/checkout-step-one.html", screenshot_path: null, created_at: iso(150) },
];
const frictions = [
  { id: 1, step_idx: 3, kind: "site", severity: "medium", expected: "The demo password next to the login form.", happened: "It was in a grey box below the fold." },
  { id: 2, step_idx: 4, kind: "agent_issue", severity: null, expected: "'click the 'Add to cart' button for the backpack' changes the page", happened: "no_effect: no recovery rung changed the page at https://www.saucedemo.com/inventory.html" },
];
let runningPolls = 0;

createServer((req, res) => {
  const url = new URL(req.url, base);
  const send = (status, body, type = "application/json") => {
    res.writeHead(status, { "Content-Type": type });
    res.end(type === "application/json" ? JSON.stringify(body) : body);
  };
  console.log(req.method, url.pathname + url.search, "auth:", req.headers.apikey ? "present" : "missing");
  if (url.pathname === "/shot.png") return send(200, readFileSync(shot), "image/png");
  if (req.method === "POST" && url.pathname === "/rest/v1/rpc/enqueue_web_run") {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      const body = JSON.parse(raw);
      console.log("  rpc args:", JSON.stringify({ ...body, p_ip_hash: body.p_ip_hash.slice(0, 8) + "…" }));
      if (body.p_url.includes("full")) return send(200, { error: "queue_full" });
      if (body.p_url.includes("limit")) return send(200, { error: "rate_limited", retry_after_seconds: 1234 });
      return send(200, { id: ids.queued });
    });
    return;
  }
  const id = (url.searchParams.get("id") || url.searchParams.get("run_id") || "").replace("eq.", "");
  if (url.pathname === "/rest/v1/runs") {
    let r = runs[id];
    if (r && id === ids.running) {
      runningPolls += 1; // flips to done after a few polls, to test that polling stops
      if (runningPolls > 3) r = { ...runs[ids.done], id };
    }
    return send(200, r ? [r] : []);
  }
  const visible = id === ids.queued ? 0 : id === ids.running ? Math.min(steps.length, 1 + runningPolls) : steps.length;
  if (url.pathname === "/rest/v1/steps") return send(200, runs[id] ? steps.slice(0, visible) : []);
  if (url.pathname === "/rest/v1/frictions") return send(200, runs[id] && id !== ids.queued ? frictions : []);
  send(404, { message: "not found" });
}).listen(port, "127.0.0.1", () => console.log("fake postgrest on", base));

