// Fake Supabase REST endpoint for the ways-in checks. Usage: node fake-postgrest-v3.mjs <port>
// GET /__last returns the arguments of the last enqueue_web_run call and every request path seen.
import { createServer } from "node:http";

const port = Number(process.argv[2]);
const ID = (n) => `00000000-0000-4000-8000-00000000000${n}`;
const now = Date.now();
const iso = (s) => new Date(now - s * 1000).toISOString();
let last = null;
const seen = [];

const review = {
  what_it_does: { clear: "partly", summary: "It says it helps teams plan projects, but not how, or what makes it different." },
  who_its_for: { clear: "no", summary: "Nothing on the page says who the product is for." },
  main_action: { obvious: "yes", summary: "The green 'Get started' button is the obvious next step." },
  hesitations: ["The page asks for an account before showing any product screenshot.", "Pricing is not visible anywhere."],
  suggestions: ["Add one screenshot of a finished project board above the fold.", "Name the audience in the headline.", "Show pricing or say it is free."],
};
const base = {
  url: "https://acme.example/", start_url: null, has_test_login: false, first_impression: review, entry: null,
  goal: "Work out what this product does and try its main feature as a first-time visitor.",
  status: "done", outcome: "blocked", reason: "The app needs a login before anything else.", cost_usd: "0.0121",
  brain_model: "claude-haiku-5-5", created_at: iso(300), started_at: iso(200), finished_at: iso(60),
};
const entry = (extra) => ({
  start_link: null, test_login: "not_provided", self_signup: "not_used", third_party_options: [],
  created_account_email: null, blocked_at_login: false, ...extra,
});
const runs = {
  [ID(1)]: { ...base, id: ID(1), entry: entry({ blocked_at_login: true }),
    reason: "Every page after the landing page asks for a login, and no test account was available." },
  [ID(2)]: { ...base, id: ID(2), start_url: "https://acme.example/demo", has_test_login: true, outcome: "achieved",
    reason: "I signed in with the test account and opened the first project, Apollo.",
    entry: entry({ start_link: "https://acme.example/demo", test_login: "used" }) },
  [ID(3)]: { ...base, id: ID(3), outcome: "achieved", reason: "I created an account and reached the dashboard.",
    entry: entry({ self_signup: "used", created_account_email: "first.user.1a2b3c4d@example.com" }) },
  [ID(4)]: { ...base, id: ID(4), reason: "Signing up needs the new account's email to be verified, which the visitor cannot do.",
    entry: entry({ self_signup: "blocked_verification", created_account_email: "first.user.9f8e7d6c@example.com", blocked_at_login: true }) },
  [ID(5)]: { ...base, id: ID(5), reason: "The only ways in offered were third-party sign-in options (Google, GitHub).",
    entry: entry({ self_signup: "blocked_third_party", third_party_options: ["Google", "GitHub"], blocked_at_login: true }) },
  [ID(6)]: { ...base, id: ID(6), status: "running", outcome: null, reason: null, finished_at: null },
  [ID(7)]: { ...base, id: ID(7), first_impression: null, outcome: "gave_up", reason: "I could not find the main feature.", entry: entry({}) },
};

createServer((req, res) => {
  const url = new URL(req.url, `http://127.0.0.1:${port}`);
  const send = (status, body) => {
    res.writeHead(status, { "Content-Type": "application/json" });
    res.end(JSON.stringify(body));
  };
  if (url.pathname === "/__last") return send(200, { last, seen });
  seen.push(`${req.method} ${url.pathname} select=${url.searchParams.get("select") ?? ""}`);
  if (req.method === "POST" && url.pathname === "/rest/v1/rpc/enqueue_web_run") {
    let raw = "";
    req.on("data", (c) => (raw += c));
    req.on("end", () => {
      last = JSON.parse(raw);
      send(200, { id: ID(1) });
    });
    return;
  }
  const id = (url.searchParams.get("id") || url.searchParams.get("run_id") || "").replace("eq.", "");
  if (url.pathname === "/rest/v1/runs") {
    const select = url.searchParams.get("select") ?? "";
    const wanted = select.split(",").map((s) => s.trim());
    const row = runs[id];
    return send(200, row ? [Object.fromEntries(Object.entries(row).filter(([k]) => wanted.includes(k)))] : []);
  }
  if (url.pathname === "/rest/v1/steps" || url.pathname === "/rest/v1/frictions") return send(200, []);
  send(404, { message: "not found" });
}).listen(port, "127.0.0.1", () => console.log("fake postgrest on", port));

