        and parameter.kind
        in {inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY}
    ) or any(item.kind is inspect.Parameter.VAR_KEYWORD for item in parameters.values())


